const sd = $getWorkflowStaticData('global');

// Candidate list: prefer workflow memory, then fall back to the upstream nodes.
// The fallbacks cover pinned or partial executions where Collect Candidates'
// code did not actually run and therefore never wrote to static data.
let candidates = sd.candidates || [];
if (candidates.length === 0) {
  try { candidates = $('Handle Rejection').first().json.candidates || []; } catch (e) {}
}
if (candidates.length === 0) {
  try { candidates = $('Collect Candidates').first().json.candidates || []; } catch (e) {}
}

const out = ($input.first().json.output) || {};
let picked = out.article;
if (Array.isArray(picked)) picked = picked[0];
picked = picked || {};

// The model must pick from the real list; never trust an invented link
let match = candidates.find(c => c.link === picked.link);
if (!match && picked.title) {
  const t = String(picked.title).toLowerCase().trim();
  match = candidates.find(c => c.title.toLowerCase().trim() === t);
}
if (!match && candidates.length > 0) {
  match = candidates.slice().sort((a, b) => new Date(b.isoDate) - new Date(a.isoDate))[0];
}
// Last resort: trust the picker's own output so the flow never dies here
if (!match && picked.link) {
  match = { title: picked.title || picked.link, link: picked.link, isoDate: picked.isoDate || new Date().toISOString() };
}
if (!match) {
  throw new Error('Select Article received no candidate list and no usable pick from News Picker. Run the full flow so Collect Candidates executes (unpin it if pinned).');
}

sd.candidates = candidates;
sd.attemptCount = (sd.attemptCount || 0) + 1;
sd.currentSelection = { title: match.title, link: match.link };

return [{ json: { title: match.title, link: match.link, isoDate: match.isoDate, attempt: sd.attemptCount } }];

const sd = $getWorkflowStaticData('global');
const sel = sd.currentSelection || {};
const j = $input.first().json;

let content = '';
if (typeof j.content === 'string') content = j.content;
else if (j.data && typeof j.data.content === 'string') content = j.data.content;
else if (typeof j.data === 'string') content = j.data;
else if (typeof j.text === 'string') content = j.text;
content = content.trim();

let publication = '';
const m = String(sel.link || '').match(/^https?:\/\/(?:www\.)?([^\/]+)/i);
if (m) publication = m[1];

return [{ json: {
  title: sel.title || j.title || '',
  link: sel.link || '',
  publication: publication,
  content: content.slice(0, 20000),
  contentLength: content.length,
} }];

