const sd = $getWorkflowStaticData('global');
const sel = sd.currentSelection || {};

// Record the published topic so future runs skip it (pruned after 7 days)
if (sel.title) {
  sd.usedTopics = [...(sd.usedTopics || []), { title: sel.title, ts: Date.now() }].slice(-50);
}
sd.candidates = [];
sd.currentSelection = null;
sd.attemptCount = 0;

return [{ json: { published: true, title: sel.title || '', link: sel.link || '' } }];

const sd = $getWorkflowStaticData('global');
const sel = sd.currentSelection || {};
const MAX_ATTEMPTS = 3;

// Remember the rejected/failed article so it is never picked again
if (sel.link) {
  sd.rejectedLinks = [...(sd.rejectedLinks || []), sel.link].slice(-100);
  sd.candidates = (sd.candidates || []).filter(c => c.link !== sel.link);
}
sd.currentSelection = null;

const attempts = sd.attemptCount || 0;
const remaining = (sd.candidates || []).length;

if (attempts >= MAX_ATTEMPTS) {
  return [{ json: { retry: false, reason: 'I tried ' + attempts + ' articles this run and none was approved or usable, so I am stopping this run.' } }];
}
if (remaining === 0) {
  return [{ json: { retry: false, reason: 'No candidate articles are left to try after the last rejection.' } }];
}

return [{ json: {
  retry: true,
  found: true,
  candidateCount: remaining,
  candidates: sd.candidates,
  usedTopics: (sd.usedTopics || []).map(t => t.title),
} }];
